using Avalonia.Controls;
using Avalonia.Platform;
using GmailWatcher.Desktop.Presentation;

namespace GmailWatcher.Desktop.Platform;

/// <summary>
/// Loads the packaged app/tray icons (Assets/*.ico, regenerated by scripts/make-icon.ps1). The plain one is also the
/// executable's ApplicationIcon, so Explorer, the taskbar, the tray and notifications all show one mark; the tray adds a
/// small status dot while syncing (white) or when something needs the user (red).
/// </summary>
public static class AppIconFactory
{
    public static readonly Uri IconUri = new("avares://GmailWatcher/Assets/GmailWatcher.ico");

    public static Uri UriFor(TrayIconKind kind) => kind switch
    {
        TrayIconKind.Busy => new Uri("avares://GmailWatcher/Assets/GmailWatcher-busy.ico"),
        TrayIconKind.Attention => new Uri("avares://GmailWatcher/Assets/GmailWatcher-attention.ico"),
        _ => IconUri,
    };

    public static WindowIcon Create(TrayIconKind kind = TrayIconKind.Normal)
    {
        using var stream = AssetLoader.Open(UriFor(kind));
        return new WindowIcon(stream);
    }
}
